window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0a6d331f5d194fd9"]={"versions": [{"id": "FIG-0a6d331f5d194fd9", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Schichtenstapels des CAN-Netzwerkmanagements in der AUTOSAR-Basissoftwarearchitektur (Classic Platform). Das Diagramm veranschaulicht die vertikale Einbettung des CAN-spezifischen Netzwerkmanagements zwischen dem generischen Netzwerkmanagement-Interface und der CAN-Treiberabstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei Schichten mit vier Modulinstanzen (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li>Oben: <code>:Nm</code> (generische Netzwerkmanagement-Schnittstelle) als breiter Schichtenblock über die gesamte Stapelbreite.\n</li><li>Mitte: Zwei nebeneinander platzierte Instanzen <code>:CanNm</code> (CAN-spezifisches Netzwerkmanagement), die parallele Kanäle bzw. mehrfache Instanziierung der Modulschicht abbilden.\n</li><li>Unten: <code>:CanIf</code> (CAN Interface) als breiter Schichtenblock über die gesamte Stapelbreite unterhalb der <code>:CanNm</code>-Instanzen.\n</li></ul>\n<p class=\"fig-p\">Alle Instanzen sind als UML-Komponenten mit Komponentensymbol oben rechts und unterstrichener Bezeichnung (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) visualisiert. Explizite Ports, Konnektoren oder Schnittstellenbezeichner sind nicht eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtendiagramm ohne dynamische Aufruf- oder Nachrichtensequenzen. Der vertikale Stapel impliziert den Kontroll- und Datenfluss von oben (<code>:Nm</code>) nach unten (<code>:CanIf</code>) bei Sende- bzw. Steuerungsanforderungen sowie von unten nach oben bei Empfangsmeldungen und Statusweiterleitungen über die <code>:CanNm</code>-Instanzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Übersichtsdarstellung der Modulhierarchie. Sie verdeutlicht die Vermittlerrolle von <code>CanNm</code> zwischen dem busunabhängigen <code>Nm</code> und dem hardwarenahen <code>CanIf</code> sowie die architektonische Fähigkeit zur parallelen Instanziierung mehrerer <code>CanNm</code>-Instanzen für verschiedene CAN-Netzwerke/Kanäle. Konkrete API-Funktionen, Callbacks und PDU-Routen sind nicht abgebildet und der Spezifikation im Fließtext zu entnehmen.</p>"}, {"id": "FIG-25990497e482f5a5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Schichtenstapels des CAN-Netzwerkmanagements in der AUTOSAR-Basissoftwarearchitektur (Classic Platform). Das Diagramm veranschaulicht die vertikale Einbettung des CAN-spezifischen Netzwerkmanagements zwischen dem generischen Netzwerkmanagement-Interface und der CAN-Treiberabstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei vertikal gestapelte Schichten mit jeweils einer Modulinstanz (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li>Oben: <code>:Nm</code> (generische Netzwerkmanagement-Schnittstelle) als breiter Schichtenblock.\n</li><li>Mitte: Eine einzelne <code>:CanNm</code>-Komponente (CAN-spezifisches Netzwerkmanagement) in voller Breite des Stapels.\n</li><li>Unten: <code>:CanIf</code> (CAN Interface) als breiter Schichtenblock.\n</li></ul>\n<p class=\"fig-p\">Alle Instanzen sind als UML-Komponenten mit Komponentensymbol oben rechts und unterstrichener Bezeichnung (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) ausgeführt. Explizite Schnittstellen, Ports oder Konnektoren sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtendiagramm ohne dynamische Abläufe. Die Schichtung impliziert die vertikale Interaktion zwischen <code>:Nm</code>, der singulären <code>:CanNm</code>-Zwischenschicht und <code>:CanIf</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenzdarstellung des AUTOSAR NM Stacks auf CAN. Sie definiert die grundlegende Drei-Schichten-Hierarchie mit singulärer Repräsentation des Moduls <code>CanNm</code> zwischen <code>Nm</code> und <code>CanIf</code>. Konkrete API-Signaturen und kanalspezifische Konfigurationen sind der Spezifikation zu entnehmen.</p>"}, {"id": "FIG-ccf363922e183a1b", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Schichtenstapels des CAN-Netzwerkmanagements in der AUTOSAR-Basissoftwarearchitektur (Classic Platform). Das Diagramm veranschaulicht die vertikale Einbettung des CAN-spezifischen Netzwerkmanagements zwischen dem generischen Netzwerkmanagement-Interface und der CAN-Treiberabstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei vertikal gestapelte Schichten mit jeweils einer Modulinstanz (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li>Oben: <code>:Nm</code> (generische Netzwerkmanagement-Schnittstelle) als breiter Schichtenblock.\n</li><li>Mitte: Eine einzelne <code>:CanNm</code>-Komponente (CAN-spezifisches Netzwerkmanagement) in voller Breite des Stapels.\n</li><li>Unten: <code>:CanIf</code> (CAN Interface) als breiter Schichtenblock.\n</li></ul>\n<p class=\"fig-p\">Alle Instanzen sind als UML-Komponenten mit Komponentensymbol oben rechts und unterstrichener Bezeichnung (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) ausgeführt. Explizite Schnittstellen, Ports oder Konnektoren sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtendiagramm ohne dynamische Abläufe. Die Schichtung impliziert die vertikale Interaktion zwischen <code>:Nm</code>, der singulären <code>:CanNm</code>-Zwischenschicht und <code>:CanIf</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenzdarstellung des AUTOSAR NM Stacks auf CAN. Sie definiert die grundlegende Drei-Schichten-Hierarchie mit singulärer Repräsentation des Moduls <code>CanNm</code> zwischen <code>Nm</code> und <code>CanIf</code>. Konkrete API-Signaturen und kanalspezifische Konfigurationen sind der Spezifikation zu entnehmen.</p>"}, {"id": "FIG-3d7801ef075d47b1", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Schichtenstapels des CAN-Netzwerkmanagements in der AUTOSAR-Basissoftwarearchitektur (Classic Platform). Das Diagramm veranschaulicht die vertikale Einbettung des CAN-spezifischen Netzwerkmanagements zwischen dem generischen Netzwerkmanagement-Interface und der CAN-Treiberabstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei vertikal gestapelte Schichten mit jeweils einer Modulinstanz (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li>Oben: <code>:Nm</code> (generische Netzwerkmanagement-Schnittstelle) als breiter Schichtenblock.\n</li><li>Mitte: <code>:CanNm</code> (CAN-spezifisches Netzwerkmanagement) als breiter Schichtenblock.\n</li><li>Unten: <code>:CanIf</code> (CAN Interface) als breiter Schichtenblock.\n</li></ul>\n<p class=\"fig-p\">Alle Komponenten tragen das UML-Komponentensymbol oben rechts. Die Instanznamen (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) sind nicht unterstrichen. Explizite Schnittstellen, Ports oder Konnektoren sind nicht eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtendiagramm ohne dynamische Abläufe. Die Schichtung impliziert die vertikale Interaktion zwischen <code>:Nm</code>, der singulären <code>:CanNm</code>-Zwischenschicht und <code>:CanIf</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenzdarstellung des AUTOSAR NM Stacks auf CAN. Sie definiert die grundlegende Drei-Schichten-Hierarchie mit singulärer Repräsentation des Moduls <code>CanNm</code> zwischen <code>Nm</code> und <code>CanIf</code>. Konkrete API-Signaturen und kanalspezifische Konfigurationen sind der Spezifikation zu entnehmen.</p>"}, {"id": "FIG-cde80468f23c10d1", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Schichtenstapels des CAN-Netzwerkmanagements in der AUTOSAR-Basissoftwarearchitektur (Classic Platform). Das Diagramm veranschaulicht die vertikale Einbettung des CAN-spezifischen Netzwerkmanagements zwischen dem generischen Netzwerkmanagement-Interface und der CAN-Treiberabstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei vertikal gestapelte Schichten mit jeweils einer Modulinstanz (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li>Oben: <code>:Nm</code> (generische Netzwerkmanagement-Schnittstelle) als breiter Schichtenblock.\n</li><li>Mitte: <code>:CanNm</code> (CAN-spezifisches Netzwerkmanagement) als breiter Schichtenblock.\n</li><li>Unten: <code>:CanIf</code> (CAN Interface) als breiter Schichtenblock.\n</li></ul>\n<p class=\"fig-p\">Alle Komponenten tragen das UML-Komponentensymbol oben rechts. Die Instanznamen (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) sind nicht unterstrichen. Explizite Schnittstellen, Ports oder Konnektoren sind nicht eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtendiagramm ohne dynamische Abläufe. Die Schichtung impliziert die vertikale Interaktion zwischen <code>:Nm</code>, der singulären <code>:CanNm</code>-Zwischenschicht und <code>:CanIf</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenzdarstellung des AUTOSAR NM Stacks auf CAN. Sie definiert die grundlegende Drei-Schichten-Hierarchie mit singulärer Repräsentation des Moduls <code>CanNm</code> zwischen <code>Nm</code> und <code>CanIf</code>. Konkrete API-Signaturen und kanalspezifische Konfigurationen sind der Spezifikation zu entnehmen.</p>"}, {"id": "FIG-e8b0b56baf42298b", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Schichtenstapels des CAN-Netzwerkmanagements in der AUTOSAR-Basissoftwarearchitektur (Classic Platform). Das Diagramm veranschaulicht die vertikale Einbettung des CAN-spezifischen Netzwerkmanagements zwischen dem generischen Netzwerkmanagement-Interface und der CAN-Treiberabstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei vertikal gestapelte Schichten mit jeweils einer Modulinstanz (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li>Oben: <code>:Nm</code> (generische Netzwerkmanagement-Schnittstelle) als breiter Schichtenblock.\n</li><li>Mitte: <code>:CanNm</code> (CAN-spezifisches Netzwerkmanagement) als breiter Schichtenblock.\n</li><li>Unten: <code>:CanIf</code> (CAN Interface) als breiter Schichtenblock.\n</li></ul>\n<p class=\"fig-p\">Alle Komponenten tragen das UML-Komponentensymbol oben rechts. Die Instanznamen (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) sind nicht unterstrichen. Explizite Schnittstellen, Ports oder Konnektoren sind nicht eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtendiagramm ohne dynamische Abläufe. Die Schichtung impliziert die vertikale Interaktion zwischen <code>:Nm</code>, der singulären <code>:CanNm</code>-Zwischenschicht und <code>:CanIf</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenzdarstellung des AUTOSAR NM Stacks auf CAN. Sie definiert die grundlegende Drei-Schichten-Hierarchie mit singulärer Repräsentation des Moduls <code>CanNm</code> zwischen <code>Nm</code> und <code>CanIf</code>. Konkrete API-Signaturen und kanalspezifische Konfigurationen sind der Spezifikation zu entnehmen.</p>"}], "trans": [{"from": "FIG-0a6d331f5d194fd9", "to": "FIG-25990497e482f5a5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Komponente :CanNm</strong>: Zwei parallel dargestellte <code>:CanNm</code>-Instanzen werden durch eine einzige, horizontal durchgehende <code>:CanNm</code>-Komponenteninstanz ersetzt; die Mehrkanal-/Multi-Instanz-Darstellung im Schichtenstapel entfällt im Diagramm.\n</li></ul>"}, {"from": "FIG-25990497e482f5a5", "to": "FIG-ccf363922e183a1b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ccf363922e183a1b", "to": "FIG-3d7801ef075d47b1", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Typografie / Formatierung</strong>: Die Unterstreichung der anonymen Instanznamen (<code>:Nm</code>, <code>:CanNm</code>, <code>:CanIf</code>) entfällt bei allen drei Komponenten.\n</li><li><strong>Schriftbild</strong>: Wechsel der Schriftart bzw. Neu-Rendering des Textes.\n</li></ul>"}, {"from": "FIG-3d7801ef075d47b1", "to": "FIG-cde80468f23c10d1", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cde80468f23c10d1", "to": "FIG-e8b0b56baf42298b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
